// Package envfile renders the .env.prod file a Kuniel-shaped docker-compose
// project reads (domain/image/Postgres are always present; JWT, admin,
// email, and object storage are each optional blocks so this fits Spring
// Boot + Postgres projects that don't need all of them) — filled in from
// wizard answers instead of hand-edited.
package envfile

import (
	"bufio"
	"bytes"
	"fmt"
	"os"
	"strings"
	"text/template"
)

// Answers holds every value the compose project's .env.prod needs. The
// Has* fields gate whole sections of the generated file — false omits that
// section (and its keys) entirely rather than writing them out blank.
type Answers struct {
	AppDomain    string
	CertbotEmail string
	AppImage     string

	PostgresDB       string
	PostgresUser     string
	PostgresPassword string
	BackupKeepDays   string

	CorsAllowedOrigins string

	HasJWT         bool
	CertsMountPath string // e.g. /etc/app/certs — where certs/ is mounted in the app container

	HasAdmin      bool
	AdminEmail    string
	AdminPassword string
	AdminFullName string

	HasEmail     bool
	ResendAPIKey string
	ResendFrom   string

	HasObjectStorage bool
	S3Endpoint       string
	S3AccessKey      string
	S3SecretKey      string
	S3Bucket         string
	S3Region         string

	// Extra holds variables this template knows nothing about, collected
	// because the project's own Spring configuration requires them. Ordered,
	// not a map: the generated file has to come out byte-identical for the
	// same answers.
	Extra []KV

	// Carried holds keys found in a previous .env.prod that nothing here
	// writes. Overwriting the file would otherwise silently drop whatever was
	// added by hand — the backup keeps it, but only for someone who thinks to
	// look.
	Carried []KV
}

// KV is one env-file line.
type KV struct {
	Key   string
	Value string
}

const envTemplate = `# Generated by serv-kun springboot setup. Keep this out of git.
# Values are double-quoted and escaped so characters like $ survive Compose's
# interpolation — see quoteValue.

# --- Domain / TLS (nginx + certbot) ---
APP_DOMAIN={{q .AppDomain}}
CERTBOT_EMAIL={{q .CertbotEmail}}

# --- Docker image ---
APP_IMAGE={{q .AppImage}}

# --- Postgres (self-hosted, internal network only) ---
POSTGRES_DB={{q .PostgresDB}}
POSTGRES_USER={{q .PostgresUser}}
POSTGRES_PASSWORD={{q .PostgresPassword}}
SPRING_DATASOURCE_URL={{q (printf "jdbc:postgresql://postgres:5432/%s" .PostgresDB)}}
SPRING_DATASOURCE_USERNAME={{q .PostgresUser}}
SPRING_DATASOURCE_PASSWORD={{q .PostgresPassword}}
BACKUP_KEEP_DAYS={{q .BackupKeepDays}}

# --- CORS: real origin(s) only ---
APP_CORS_ALLOWED_ORIGINS={{q .CorsAllowedOrigins}}
{{if .HasJWT}}
# --- JWT (RS256) — generated into ./certs by this wizard ---
JWT_PUBLIC_KEY={{q (printf "file:%s/public.pem" .CertsMountPath)}}
JWT_PRIVATE_KEY={{q (printf "file:%s/private.pem" .CertsMountPath)}}
{{end}}{{if .HasAdmin}}
# --- Seeded admin organiser ---
APP_ADMIN_EMAIL={{q .AdminEmail}}
APP_ADMIN_PASSWORD={{q .AdminPassword}}
APP_ADMIN_FULL_NAME={{q .AdminFullName}}
{{end}}{{if .HasEmail}}
# --- Email (Resend) ---
RESEND_API_KEY={{q .ResendAPIKey}}
RESEND_FROM={{q .ResendFrom}}
{{end}}{{if .HasObjectStorage}}
# --- Object storage (S3-compatible) ---
APP_S3_ENDPOINT={{q .S3Endpoint}}
APP_S3_ACCESS_KEY={{q .S3AccessKey}}
APP_S3_SECRET_KEY={{q .S3SecretKey}}
APP_S3_BUCKET={{q .S3Bucket}}
APP_S3_REGION={{q .S3Region}}
{{end}}{{if .Extra}}
# --- Required by this project's own Spring configuration ---
{{range .Extra}}{{.Key}}={{q .Value}}
{{end}}{{end}}{{if .Carried}}
# --- Carried over from the previous .env.prod (not written by this wizard) ---
{{range .Carried}}{{.Key}}={{q .Value}}
{{end}}{{end}}`

// quoteValue renders v as a double-quoted .env value.
//
// Compose interpolates env-file values, so an unquoted password containing $
// is silently truncated — "abc$def" arrives at the container as "abc", which
// quietly weakens a credential rather than failing. Double quotes keep spaces
// and # intact; inside them Compose still expands $ and processes backslash
// escapes (\n really does become a newline), so both need escaping too.
// Order matters: backslashes first, or the escapes added below would
// themselves be escaped.
func quoteValue(v string) string {
	v = strings.ReplaceAll(v, `\`, `\\`)
	v = strings.ReplaceAll(v, `"`, `\"`)
	v = strings.ReplaceAll(v, `$`, `$$`)
	return `"` + v + `"`
}

// unquoteValue reverses quoteValue for values read back off disk.
func unquoteValue(v string) string {
	if len(v) >= 2 && strings.HasPrefix(v, "'") && strings.HasSuffix(v, "'") {
		// Single-quoted values are literal — nothing to unescape.
		return v[1 : len(v)-1]
	}
	if len(v) < 2 || !strings.HasPrefix(v, `"`) || !strings.HasSuffix(v, `"`) {
		return v
	}

	v = v[1 : len(v)-1]
	var b strings.Builder
	for i := 0; i < len(v); i++ {
		switch {
		case v[i] == '\\' && i+1 < len(v):
			i++
			b.WriteByte(v[i])
		case v[i] == '$' && i+1 < len(v) && v[i+1] == '$':
			i++
			b.WriteByte('$')
		default:
			b.WriteByte(v[i])
		}
	}
	return b.String()
}

// Generate renders the .env.prod contents for the given answers.
func Generate(a Answers) (string, error) {
	tmpl, err := template.New("envfile").
		Funcs(template.FuncMap{"q": quoteValue}).
		Parse(envTemplate)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, a); err != nil {
		return "", err
	}
	return buf.String(), nil
}

// Keys returns the variable names defined in env-file content — used to ask
// what a generated file actually covers before comparing it against what the
// application requires.
func Keys(content string) map[string]bool {
	keys := make(map[string]bool)
	for _, line := range strings.Split(content, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		key, _, found := strings.Cut(line, "=")
		if !found {
			continue
		}
		keys[strings.TrimSpace(key)] = true
	}
	return keys
}

// Read parses a KEY=VALUE env file (blank lines and #-comments ignored) —
// used to read back APP_DOMAIN/APP_IMAGE/etc. from an existing .env.prod,
// whether this wizard wrote it or it was hand-edited afterwards.
func Read(path string) (map[string]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("open %s: %w", path, err)
	}
	defer f.Close()

	kv := make(map[string]string)
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 {
			continue
		}
		// Unquote so callers get the real value, whether this wizard wrote
		// the file (always quoted) or someone hand-edited it afterwards.
		// Without this, APP_DOMAIN="x.com" would build https://"x.com"/...
		kv[strings.TrimSpace(parts[0])] = unquoteValue(strings.TrimSpace(parts[1]))
	}
	if err := sc.Err(); err != nil {
		return nil, fmt.Errorf("read %s: %w", path, err)
	}
	return kv, nil
}
